```javascript
/**
 * Creates a debounced function that delays invoking `fn` until after `wait`
 * milliseconds have elapsed since the last time it was invoked.
 *
 * @param {Function} fn      - The function to debounce.
 * @param {number}   wait    - Delay in milliseconds.
 * @param {Object}   options - { leading: false, trailing: true }
 *   leading  – Invoke `fn` on the **leading** edge (immediately on first call).
 *   trailing – Invoke `fn` on the **trailing** edge (after the quiet period).
 *
 * @returns {Function} debounced
 *   .cancel() – Cancel the pending invocation and reset state.
 *   .flush()  – Immediately invoke the pending trailing call (if any).
 *   .pending() – Returns true if a trailing call is pending.
 */
function debounce(fn, wait, { leading = false, trailing = true } = {}) {
  let timer = null;
  let lastArgs = null;
  let lastThis = null;

  // --- internal helpers ---------------------------------------------------
  function invokeFn() {
    const args  = lastArgs;
    const self  = lastThis;
    lastArgs  = null;
    lastThis  = null;
    fn.apply(self, args);
  }

  // --- the debounced wrapper --------------------------------------------
  function debounced(...args) {
    // Decide whether to fire on the leading edge.
    // A leading call is only allowed when no timer is still pending.
    const callNow = leading && timer === null;

    // Reset any in-flight timer (classic debounce: push the deadline back).
    if (timer !== null) {
      clearTimeout(timer);
      timer = null;
    }

    if (callNow) {
      // Leading edge: invoke immediately, and mark args as consumed.
      fn.apply(this, args);
      lastArgs = null;
      lastThis = null;
    } else {
      // Stash the most-recent args for a possible trailing call.
      lastArgs = args;
      lastThis = this;
    }

    // Always arm a timer — it acts as the "cooldown" that suppresses
    // further leading calls, and as the trigger for the trailing edge.
    timer = setTimeout(() => {
      timer = null;
      if (trailing && lastArgs !== null) {
        invokeFn();
      }
    }, wait);
  }

  // --- public API -------------------------------------------------------
  debounced.cancel = function () {
    if (timer !== null) {
      clearTimeout(timer);
      timer = null;
    }
    lastArgs = null;
    lastThis = null;
  };

  debounced.flush = function () {
    if (timer !== null) {
      clearTimeout(timer);
      timer = null;
    }
    if (lastArgs !== null) {
      invokeFn();
    }
  };

  debounced.pending = function () {
    return lastArgs !== null;
  };

  return debounced;
}
```

## How it works (state machine)

| Scenario | `leading` | `trailing` | Behaviour |
|---|---|---|---|
| Classic debounce | `false` | `true` | Fires once, with the **last** args, after the quiet period. |
| "Throttle-like" first call | `true` | `false` | Fires immediately on the first call; subsequent calls within `wait` are swallowed. |
| Both edges | `true` | `true` | Fires immediately on the first call **and** once more with the latest args after the quiet period (only if a second call occurred). |
| Silent | `false` | `false` | Never fires. (Timer still runs to enforce the cooldown.) |

## Usage example

```js
// --- simple trailing debounce -------------------------------------------
const onResize = debounce(() => {
  console.log("Resize complete:", window.innerWidth);
}, 250);                       // leading: false, trailing: true

window.addEventListener("resize", onResize);
// Fires 250 ms after the last resize event.

// --- leading + trailing -----------------------------------------------
const saveBtn = debounce(() => {
  console.log("Auto-saving…");
}, 300, { leading: true, trailing: true });

// 1st click  → "Auto-saving…" (immediately)
// 2nd click  (within 300 ms) → swallowed
// 3rd click  (within 300 ms) → swallowed, timer resets
// 300 ms of quiet → "Auto-saving…" (trailing, latest state)

// --- cancel / flush ---------------------------------------------------
const search = debounce(() => {
  console.log("Searching:", input.value);
}, 400);

input.addEventListener("input", search);

input.addEventListener("blur", () => {
  search.cancel();          // discard the pending query
});

input.addEventListener("focusout", () => {
  search.flush();           // fire immediately if a query was pending
});
```

### Key design notes

* **`timer === null` is the only "cooldown" flag.** After a leading call the timer is still armed for `wait` ms, so `callNow` stays `false` during that window — giving you the "one leading call per burst" guarantee without an extra boolean.
* **`lastArgs` / `lastThis`** are the *only* arguments the trailing (or `flush`) invocation will use, guaranteeing the "latest wins" semantics.
* **`cancel()`** is safe to call at any time — it clears the timer *and* the stored args, so a subsequent `flush()` is a no-op.
* The function is allocation-light (no per-call objects beyond the args array you already pass in) and has zero external dependencies.

# Reversing a Singly Linked List in Go

```go
package main

import "fmt"

// Node represents a single element in a singly linked list.
type Node struct {
    Val  int
    Next *Node
}

// ReverseList reverses the linked list in place (O(1) extra space)
// and returns the new head.
func ReverseList(head *Node) *Node {
    var prev *Node
    curr := head

    for curr != nil {
        next := curr.Next // save the next node before overwriting the link
        curr.Next = prev  // reverse the pointer
        prev = curr       // advance prev
        curr = next       // advance curr
    }

    return prev // prev is the new head (was the old tail)
}

func main() {
    // Build list: 1 -> 2 -> 3 -> 4 -> 5
    head := &Node{Val: 1}
    head.Next = &Node{Val: 2}
    head.Next.Next = &Node{Val: 3}
    head.Next.Next.Next = &Node{Val: 4}
    head.Next.Next.Next.Next = &Node{Val: 5}

    fmt.Println("Before:", printList(head))

    head = ReverseList(head)

    fmt.Println("After: ", printList(head))
}

func printList(n *Node) string {
    var s string
    for n != nil {
        s += fmt.Sprintf("%d ", n.Val)
        n = n.Next
    }
    return s
}
```

## How it works

The classic three-pointer technique walks the list once, rewiring each `Next` pointer:

```
prev    curr    next
 nil   ->  1  ->  2  ->  3  ->  4  ->  5  -> nil

 nil  <-  1   ->  2  ->  3  ->  4  ->  5  -> nil   (step 1)
        prev  curr  next

 nil  <-  1  <-  2   ->  3  ->  4  ->  5  -> nil   (step 2)
             prev  curr  next
```

After all iterations every link is flipped and `prev` holds the original tail, which is now the head.

## Complexity

| | |
|---|---|
| **Time** | O(n) – single pass |
| **Space** | O(1) – only three pointer variables, no new nodes allocated |

